import itertools

def solve_small(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    num_perms = len(perms)

    adj = [[] for _ in range(num_perms)]
    for i in range(num_perms):
        for j in range(i + 1, num_perms):
            similar = True
            for c in range(n):
                if abs(perms[i][c] - perms[j][c]) >= 2:
                    similar = False
                    break
            if similar:
                adj[i].append(j)
                adj[j].append(i)

    # We want the maximum independent set of the graph where edges are "similar"
    # Since this is NP-hard, for small n we can use a simple recursive search or a library

    def get_max_independent_set(nodes, adj):
        if not nodes:
            return 0

        # Heuristic: pick the node with the highest degree to remove
        v = max(nodes, key=lambda x: len([neighbor for neighbor in adj[x] if neighbor in nodes]))

        # Case 1: v is not in the MIS
        res1 = get_max_independent_set([n for n in nodes if n != v], adj)

        # Case 2: v is in the MIS, so its neighbors are not
        neighbors_v = set(adj[v])
        res2 = 1 + get_max_independent_set([n for n in nodes if n != v and n not in neighbors_v], adj)

        return max(res1, res2)

    # For very small n, this will work.
    return get_max_independent_set(list(range(num_perms)), adj)

for n in range(1, 6):
    print(f"n={n}, N={solve_small(n)}")

