import networkx as nx

def solve_small(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    num_perms = len(perms)

    G = nx.Graph()
    G.add_nodes_from(range(num_perms))

    for i in range(num_perms):
        for j in range(i + 1, num_perms):
            similar = True
            for c in range(n):
                if abs(perms[i][c] - perms[j][c]) >= 2:
                    similar = False
                    break
            if similar:
                G.add_edge(i, j)

    # maximum_independent_set returns a set of nodes
    mis = nx.mis.maximum_independent_set(G)
    return len(mis)

