import itertools
import networkx as nx

def solve_small_nx(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    num_perms = len(perms)
    G = nx.Graph()
    for i in range(num_perms):
        for j in range(i + 1, num_perms):
            similar = True
            for c in range(n):
                if abs(perms[i][c] - perms[j][c]) >= 2:
                    similar = False
                    break
            if similar:
                G.add_edge(i, j)

    # Using the clique algorithm on the complement graph
    # The maximum independent set of G is the maximum clique of the complement graph G_comp
    G_comp = nx.complement(G)
    clique = nx.approximation.max_clique(G_comp) # This is an approximation
    return len(clique)

